const ADMIN_HTML = "<!doctype html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex,nofollow,noarchive\">\n<meta name=\"theme-color\" content=\"#101827\">\n<title>KURO Lab Admin</title>\n<script src=\"https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2\"></script>\n<style>\n:root{color-scheme:dark;--bg:#0b1220;--panel:#111c2d;--panel2:#172438;--line:#26364d;--text:#edf4ff;--muted:#8ea2bd;--blue:#48a9e8;--green:#46c69a;--amber:#e7b65c;--red:#ef7777}\n*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 15% -10%,#183252 0,transparent 42%),var(--bg);color:var(--text);font:15px/1.6 Inter,\"Noto Sans JP\",system-ui,sans-serif;min-height:100vh}button,input,select{font:inherit}button{cursor:pointer}.wrap{width:min(1180px,calc(100% - 36px));margin:auto}.top{height:76px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:12px;font-weight:800;letter-spacing:.02em}.mark{width:38px;height:38px;border-radius:12px;background:linear-gradient(135deg,#43b3ed,#3973d6);display:grid;place-items:center;font-weight:900;color:white}.brand small{display:block;color:var(--muted);font-size:10px;letter-spacing:.18em}.top-right{display:flex;align-items:center;gap:12px;color:var(--muted);font-size:13px}.btn{border:1px solid var(--line);background:var(--panel2);color:var(--text);border-radius:10px;padding:9px 13px}.btn.primary{background:var(--blue);color:#061321;border-color:transparent;font-weight:750}.btn:disabled{opacity:.55;cursor:wait}.main{padding:34px 0 70px}.eyebrow{color:var(--blue);font-size:11px;font-weight:800;letter-spacing:.17em;text-transform:uppercase}.heading{display:flex;justify-content:space-between;align-items:end;gap:18px;margin:7px 0 24px}.heading h1{margin:0;font-size:clamp(25px,4vw,34px);letter-spacing:-.04em}.heading p{margin:5px 0 0;color:var(--muted)}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:18px}.stat,.panel{background:linear-gradient(145deg,rgba(23,36,56,.96),rgba(15,26,42,.96));border:1px solid var(--line);border-radius:16px}.stat{padding:17px 19px}.stat span{color:var(--muted);font-size:12px}.stat strong{display:block;font-size:29px;margin-top:4px;font-variant-numeric:tabular-nums}.toolbar{display:flex;gap:10px;align-items:center;justify-content:space-between;padding:14px 16px;border-bottom:1px solid var(--line);flex-wrap:wrap}.filters{display:flex;gap:8px;flex-wrap:wrap}.filters button{border:1px solid var(--line);border-radius:9px;background:transparent;color:var(--muted);padding:7px 11px}.filters button.active{background:#1c3b59;border-color:#2e6c9c;color:#dff3ff}.search{background:#0b1524;border:1px solid var(--line);border-radius:9px;color:var(--text);padding:9px 12px;min-width:min(260px,100%);outline:none}.list{display:grid;gap:10px;padding:14px}.item{background:rgba(7,15,27,.45);border:1px solid var(--line);border-radius:13px;padding:16px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:18px}.meta{display:flex;align-items:center;gap:9px;flex-wrap:wrap;color:var(--muted);font-size:12px}.pill{border-radius:999px;padding:3px 9px;font-size:11px;font-weight:750}.pending{background:#4b3a1c;color:#f3d28d}.reviewing{background:#173d5b;color:#9bd9ff}.done{background:#164638;color:#9ce5c8}.message{white-space:pre-wrap;overflow-wrap:anywhere;margin:10px 0 0;font-size:14px}.actions{display:flex;align-items:center;gap:8px}.actions select{background:#0b1524;color:var(--text);border:1px solid var(--line);border-radius:9px;padding:8px}.empty,.error{padding:34px;text-align:center;color:var(--muted)}.error{color:#ffaaaa}.login{width:min(430px,calc(100% - 32px));margin:10vh auto;background:var(--panel);border:1px solid var(--line);border-radius:20px;padding:28px;box-shadow:0 24px 80px #0005}.login h1{margin:5px 0 4px}.login p{color:var(--muted);margin:0 0 22px}.field{display:grid;gap:7px;margin:14px 0}.field label{font-size:12px;color:var(--muted)}.field input{width:100%;background:#0b1524;color:var(--text);border:1px solid var(--line);border-radius:10px;padding:12px;outline:none}.login .btn{width:100%;margin-top:8px;padding:12px}.hint{font-size:12px;color:var(--muted);margin-top:14px}.statusline{font-size:12px;color:var(--muted)}.mode-select{background:#0b1524;color:var(--text);border:1px solid var(--line);border-radius:9px;padding:8px 10px;max-width:230px}[hidden]{display:none!important}@media(max-width:680px){.wrap{width:min(100% - 24px,1180px)}.stats{gap:8px}.stat{padding:12px}.stat strong{font-size:24px}.heading{align-items:start;flex-direction:column}.item{grid-template-columns:1fr;gap:12px}.actions{justify-content:space-between}.top-right #account{display:none}.toolbar{align-items:stretch}.search{width:100%}}\n\n.sns-tabs{display:flex;gap:8px;flex-wrap:wrap}\n.sns-tabs button{border:1px solid var(--line);border-radius:9px;background:transparent;color:var(--muted);padding:7px 12px}\n.sns-tabs button.active{background:#1c3b59;border-color:#2e6c9c;color:#dff3ff}\n.sns-toolbar-right{display:flex;gap:8px;align-items:center;flex:1;justify-content:flex-end;min-width:220px}\n.sns-toolbar-right .search{width:min(310px,100%)}\n.sns-text{white-space:pre-wrap;overflow-wrap:anywhere;margin:10px 0 0}\n.sns-actions{display:flex;align-items:center;gap:8px}\n.sns-muted{color:var(--muted);font-size:12px}\n.sns-context{padding:0 16px 12px;color:var(--muted);font-size:12px}\n.sns-context button{margin-left:8px}\n.product-select{background:#142238;color:var(--text);border:1px solid #36506d;border-radius:9px;padding:8px 10px;font-weight:700;max-width:150px}\n.sns-section-title{margin:20px 14px 0;font-size:15px;color:var(--muted)}\n\n.analytics-intro{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:16px 16px 4px}\n.analytics-intro strong{display:block;font-size:16px}.analytics-intro small{color:var(--muted)}\n.analytics-range{background:#0b1524;color:var(--text);border:1px solid var(--line);border-radius:9px;padding:8px 10px}\n.analytics-layout{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(260px,1fr);gap:14px;padding:14px}\n.analytics-card{background:rgba(7,15,27,.45);border:1px solid var(--line);border-radius:13px;padding:16px;min-width:0}\n.analytics-card h3{font-size:14px;margin:0 0 10px}.analytics-sub{font-size:12px;color:var(--muted);margin-bottom:12px}\n.analytics-legend{display:flex;gap:14px;flex-wrap:wrap;color:var(--muted);font-size:11px;margin-bottom:8px}\n.analytics-legend span{display:flex;align-items:center;gap:6px}.analytics-dot{width:8px;height:8px;border-radius:50%;display:inline-block}\n.analytics-chart{width:100%;height:auto;display:block;overflow:visible}\n.analytics-chart text{fill:var(--muted);font-size:11px}\n.analytics-chart .gridline{stroke:#314157;stroke-width:1;opacity:.62}\n.analytics-chart .series-posts{fill:none;stroke:#55b5f2;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}\n.analytics-chart .series-replies{fill:none;stroke:#a78bfa;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}\n.analytics-chart .series-chat{fill:none;stroke:#55cda5;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}\n.analytics-side{display:grid;gap:14px;align-content:start}\n.analytics-rank{list-style:none;margin:0;padding:0;display:grid;gap:10px}\n.analytics-rank li{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:13px}\n.analytics-rank li span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.analytics-rank b{font-variant-numeric:tabular-nums;color:var(--text)}\n.analytics-empty{color:var(--muted);font-size:12px;padding:8px 0}\n.analytics-note{color:var(--muted);font-size:11px;padding:0 16px 14px}\n.analytics-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;padding:0 14px 14px}\n.analytics-mini{border:1px solid var(--line);border-radius:10px;padding:10px 12px;background:rgba(7,15,27,.35)}\n.analytics-mini small{display:block;color:var(--muted);font-size:11px}.analytics-mini strong{display:block;font-size:20px;margin-top:3px;font-variant-numeric:tabular-nums}\n.live-pulse{display:inline-block;width:8px;height:8px;border-radius:50%;background:#46c69a;margin-right:7px;box-shadow:0 0 0 4px #46c69a22}\n@media(max-width:760px){.analytics-layout{grid-template-columns:1fr}.analytics-summary{grid-template-columns:repeat(2,minmax(0,1fr))}}\n\n@media(max-width:680px){.top-right{gap:6px}.product-select,.mode-select{padding:7px 6px;max-width:112px;font-size:11px}.sns-toolbar-right{justify-content:stretch}.sns-toolbar-right .search{min-width:0;flex:1}}\n\n\n.ops-filters{display:flex;gap:8px;flex-wrap:wrap;padding:14px;border-bottom:1px solid var(--line)}\n.ops-filters input,.ops-filters select{background:#0b1524;color:var(--text);border:1px solid var(--line);border-radius:9px;padding:9px 11px;min-width:130px}\n.ops-filters input{flex:1;min-width:220px}\n.ops-tablewrap{overflow:auto;padding:0 14px 14px}\n.ops-table{width:100%;min-width:900px;border-collapse:separate;border-spacing:0;font-size:13px}\n.ops-table th,.ops-table td{padding:12px 10px;border-bottom:1px solid var(--line);text-align:left;vertical-align:middle}\n.ops-table th{color:var(--muted);font-size:11px;font-weight:700;white-space:nowrap}\n.ops-table td small{display:block;color:var(--muted);font-size:11px;overflow-wrap:anywhere}\n.ops-user-actions{display:flex;gap:6px;white-space:nowrap}\n.ops-user-actions .btn{padding:6px 9px;font-size:12px}\n.ops-status{display:inline-flex;padding:3px 8px;border-radius:999px;background:#173d5b;color:#9bd9ff;font-size:11px;font-weight:750}\n.ops-status.banned{background:#4b252b;color:#ffb5b5}\n.ops-plan{color:var(--muted);font-size:11px}\n.ops-meta{padding:0 16px 12px;color:var(--muted);font-size:11px}\n@media(max-width:680px){.ops-filters input{min-width:100%}.ops-filters select{flex:1;min-width:42%}}\n\n.ops-tabs{margin:0 0 18px}\n.ops-form{padding:16px;display:grid;gap:11px;border-bottom:1px solid var(--line)}\n.ops-form input:not([type=checkbox]),.ops-form textarea{width:100%;background:#0b1524;color:var(--text);border:1px solid var(--line);border-radius:9px;padding:10px 12px;outline:none}\n.ops-form textarea{resize:vertical}\n.ops-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}\n.ops-form-grid label{display:grid;gap:6px;color:var(--muted);font-size:12px}\n.ops-check{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:13px}\n.ops-check input{width:16px;height:16px;accent-color:var(--blue)}\n.ops-form-actions{display:flex;gap:8px;flex-wrap:wrap}\n.ops-ann-item,.ops-flag-item{display:flex;align-items:start;justify-content:space-between;gap:16px;background:rgba(7,15,27,.45);border:1px solid var(--line);border-radius:12px;padding:14px}\n.ops-ann-copy,.ops-flag-copy{min-width:0;flex:1}\n.ops-ann-copy p{white-space:pre-wrap;overflow-wrap:anywhere;margin:8px 0}\n.ops-audit-meta{font:11px/1.5 ui-monospace,monospace;color:var(--muted);overflow-wrap:anywhere;margin-top:6px}\n.ops-inline-actions{display:flex;gap:7px;flex-wrap:wrap;align-items:center}\n.ops-inline-actions .btn{padding:6px 9px;font-size:12px}\n.ops-flag-key{font:12px ui-monospace,monospace;color:#9bd9ff}\n@media(max-width:680px){.ops-form-grid{grid-template-columns:1fr}.ops-ann-item,.ops-flag-item{flex-direction:column}.ops-inline-actions{width:100%}}\n\n.ops-analytics-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:14px 0 18px}\n.ops-metric{background:linear-gradient(145deg,rgba(23,36,56,.96),rgba(15,26,42,.96));border:1px solid var(--line);border-radius:13px;padding:14px 16px;min-width:0}\n.ops-metric small{display:block;color:var(--muted);font-size:11px}.ops-metric strong{display:block;font-size:26px;font-variant-numeric:tabular-nums;margin-top:4px}\n.ops-analytics-panel{margin-bottom:16px}.ops-active-chart{padding:18px;display:flex;align-items:end;gap:5px;min-height:190px;overflow-x:auto}\n.ops-chart-day{flex:1;min-width:14px;display:flex;flex-direction:column;align-items:center;justify-content:end;height:150px;gap:6px}\n.ops-chart-bar{width:min(100%,22px);min-height:2px;border-radius:5px 5px 2px 2px;background:linear-gradient(180deg,#55b5f2,#3973d6)}\n.ops-chart-day small{font-size:9px;color:var(--muted);white-space:nowrap;writing-mode:vertical-rl}\n.ops-analytics-columns{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n.ops-analytics-panel .ops-tablewrap{padding:0 14px 14px}\n.ops-analytics-table{width:100%;border-collapse:collapse;font-size:12px}.ops-analytics-table th,.ops-analytics-table td{padding:9px 7px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}.ops-analytics-table th{color:var(--muted);font-weight:650;white-space:nowrap}\n.ops-retention-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding:16px}\n.ops-retention-card{background:rgba(7,15,27,.45);border:1px solid var(--line);border-radius:11px;padding:14px}.ops-retention-card strong{display:block;font-size:24px}.ops-retention-card small{color:var(--muted)}\n.ops-error-search{grid-template-columns:minmax(0,1fr) auto;align-items:center}.ops-error-item{padding:12px 16px;border-bottom:1px solid var(--line);font-size:12px}.ops-error-item b{color:#ffb5b5}.ops-error-item small{display:block;color:var(--muted);margin-top:3px}\n@media(max-width:900px){.ops-analytics-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.ops-analytics-columns{grid-template-columns:1fr}}\n@media(max-width:520px){.ops-retention-grid{grid-template-columns:1fr}.ops-error-search{grid-template-columns:1fr}}\n</style>\n</head>\n<body>\n<section id=\"loginView\" class=\"login\">\n<div class=\"brand\"><div class=\"mark\">K</div><div>KURO Lab<small>ADMIN CONSOLE</small></div></div>\n<div style=\"height:24px\"></div><div class=\"eyebrow\">Secure sign in</div><h1>管理者ログイン</h1><p>KURO Labの管理者アカウントでログインしてください。</p><div class=\"field\"><label for=\"modeSelect\">通信方式</label><select class=\"mode-select\" id=\"modeSelect\"><option value=\"supabase\">Supabase版（直接通信）</option><option value=\"gas\">GAS版（GAS経由）</option></select></div>\n<form id=\"loginForm\">\n<div class=\"field\"><label for=\"email\">メールアドレス</label><input id=\"email\" type=\"email\" value=\"kurogamesmaker@gmail.com\" autocomplete=\"username\" required></div>\n<div class=\"field\"><label for=\"password\">パスワード</label><input id=\"password\" type=\"password\" autocomplete=\"current-password\" required></div>\n<button class=\"btn primary\" id=\"loginButton\">ログイン</button>\n<div id=\"loginError\" class=\"hint\" role=\"alert\"></div>\n</form><div class=\"hint\">この画面は管理者専用です。一般アカウントではアクセスできません。</div>\n</section>\n<div id=\"appView\" hidden>\n<header class=\"top\"><div class=\"wrap\" style=\"display:flex;align-items:center;justify-content:space-between\"><div class=\"brand\"><div class=\"mark\">K</div><div>KURO Lab<small>ADMIN CONSOLE</small></div></div><div class=\"top-right\"><span id=\"account\"></span><select class=\"product-select\" id=\"productSelect\" aria-label=\"管理対象\"><option value=\"lab\">KURO Lab</option><option value=\"sns\">KURO SNS</option><option value=\"ops\">運営管理</option></select><select class=\"mode-select\" id=\"modeSelectTop\" aria-label=\"通信方式\"><option value=\"supabase\">Supabase版</option><option value=\"gas\">GAS版</option></select><button class=\"btn\" id=\"notifyButton\">通知を許可</button><button class=\"btn\" id=\"logoutButton\">ログアウト</button></div></div></header>\n<main id=\"labAdminSection\" class=\"wrap main\">\n<div class=\"eyebrow\">Workspace / Requests</div>\n<div class=\"heading\"><div><h1>リクエストBOX</h1><p>利用者から届いたリクエストを確認・管理します。</p></div><div class=\"statusline\" id=\"connection\">接続中…</div></div>\n<div class=\"stats\"><div class=\"stat\"><span>すべて</span><strong id=\"totalCount\">—</strong></div><div class=\"stat\"><span>未対応</span><strong id=\"pendingCount\">—</strong></div><div class=\"stat\"><span>確認中</span><strong id=\"reviewCount\">—</strong></div></div>\n<section class=\"panel\"><div class=\"toolbar\"><div class=\"filters\" id=\"filters\"><button class=\"active\" data-filter=\"all\">すべて</button><button data-filter=\"pending\">未対応</button><button data-filter=\"reviewing\">確認中</button><button data-filter=\"done\">対応済み</button></div><input class=\"search\" id=\"search\" type=\"search\" placeholder=\"内容を検索…\"></div><div class=\"list\" id=\"requestList\"><div class=\"empty\">読み込み中…</div></div></section>\n</main>\n\n\n\n<main id=\"opsAdminSection\" class=\"wrap main\" hidden>\n <div class=\"eyebrow\">KURO Lab / Operations</div>\n <div class=\"heading\">\n  <div><h1>運営管理</h1><p>アカウント・運用設定・お知らせを管理します。強い操作は監査ログに記録されます。</p></div>\n  <div class=\"statusline\" id=\"opsConnection\">準備中…</div>\n </div>\n <div class=\"sns-tabs ops-tabs\" id=\"opsTabs\">\n  <button class=\"active\" data-ops-tab=\"users\">ユーザー</button>\n  <button data-ops-tab=\"audit\">監査ログ</button>\n  <button data-ops-tab=\"announcements\">お知らせ</button>\n  <button data-ops-tab=\"flags\">機能ON/OFF</button>\n  <button data-ops-tab=\"analytics\">利用分析</button>\n </div>\n <div id=\"opsUsersView\">\n  <div class=\"stats\">\n   <div class=\"stat\"><span>登録ユーザー</span><strong id=\"opsTotalUsers\">—</strong></div>\n   <div class=\"stat\"><span>利用可能</span><strong id=\"opsActiveUsers\">—</strong></div>\n   <div class=\"stat\"><span>停止中</span><strong id=\"opsBannedUsers\">—</strong></div>\n  </div>\n  <section class=\"panel\">\n   <div class=\"toolbar\"><strong>ユーザー・アカウント管理</strong><button class=\"btn\" id=\"opsUsersRefresh\">更新</button></div>\n   <div class=\"ops-filters\">\n    <input id=\"opsUsersSearch\" type=\"search\" placeholder=\"メール・ユーザー名・表示名・IDで検索\">\n    <select id=\"opsStatusFilter\" aria-label=\"アカウント状態\"><option value=\"all\">状態：すべて</option><option value=\"active\">利用可能</option><option value=\"banned\">停止中</option></select>\n    <select id=\"opsCreatedFilter\" aria-label=\"登録日時\"><option value=\"all\">登録日：すべて</option><option value=\"7\">過去7日</option><option value=\"30\">過去30日</option><option value=\"90\">過去90日</option></select>\n    <select id=\"opsActivityFilter\" aria-label=\"最終ログイン\"><option value=\"all\">最終ログイン：すべて</option><option value=\"7\">7日以内</option><option value=\"30\">30日以内</option><option value=\"90\">90日以内</option><option value=\"never\">ログイン記録なし</option></select>\n    <select id=\"opsBoardsFilter\" aria-label=\"ボード数\"><option value=\"all\">ボード数：すべて</option><option value=\"0\">0</option><option value=\"1\">1</option><option value=\"2-5\">2〜5</option><option value=\"6\">6以上</option></select>\n    <select id=\"opsPlanFilter\" aria-label=\"プラン\"><option value=\"all\">プラン：すべて</option><option value=\"free\">無料</option><option value=\"paid\">有料</option><option value=\"unlinked\">未連携</option></select>\n   </div>\n   <div class=\"ops-meta\" id=\"opsUsersMeta\">アカウント一覧を読み込みます。</div>\n   <div class=\"ops-tablewrap\" id=\"opsUsersList\"><div class=\"empty\">読み込み中…</div></div>\n  </section>\n </div>\n <div id=\"opsAuditView\" hidden>\n  <section class=\"panel\">\n   <div class=\"toolbar\"><div><strong>操作監査ログ</strong><div class=\"sns-muted\">誰が・いつ・何を変更したかを記録します。</div></div><button class=\"btn\" id=\"opsAuditRefresh\">更新</button></div>\n   <div class=\"list\" id=\"opsAuditList\"><div class=\"empty\">読み込み中…</div></div>\n  </section>\n </div>\n <div id=\"opsAnnouncementsView\" hidden>\n  <section class=\"panel\">\n   <div class=\"toolbar\"><div><strong>お知らせ・メンテナンス配信</strong><div class=\"sns-muted\">公開期間を指定し、ユーザー側に配信します。</div></div><button class=\"btn\" id=\"opsAnnouncementsRefresh\">更新</button></div>\n   <form id=\"opsAnnouncementForm\" class=\"ops-form\">\n    <input id=\"opsAnnTitle\" maxlength=\"120\" required placeholder=\"お知らせのタイトル\">\n    <textarea id=\"opsAnnBody\" maxlength=\"8000\" rows=\"4\" required placeholder=\"本文\"></textarea>\n    <input id=\"opsAnnHref\" type=\"url\" placeholder=\"リンク（任意・HTTPSのみ）\">\n    <div class=\"ops-form-grid\"><label>公開開始<input id=\"opsAnnStarts\" type=\"datetime-local\"></label><label>公開終了（任意）<input id=\"opsAnnEnds\" type=\"datetime-local\"></label></div>\n    <label class=\"ops-check\"><input id=\"opsAnnPublished\" type=\"checkbox\"> 保存後すぐ公開する</label>\n    <div class=\"ops-form-actions\"><button type=\"submit\" class=\"btn primary\" id=\"opsAnnSave\">お知らせを保存</button><button class=\"btn\" type=\"button\" id=\"opsAnnCancel\" hidden>編集をキャンセル</button></div>\n    <div class=\"sns-muted\" id=\"opsAnnStatus\">公開中のお知らせはユーザー側の表示条件に従って配信されます。</div>\n   </form>\n   <div class=\"list\" id=\"opsAnnouncementsList\"><div class=\"empty\">読み込み中…</div></div>\n  </section>\n </div>\n <div id=\"opsFlagsView\" hidden>\n  <section class=\"panel\">\n   <div class=\"toolbar\"><div><strong>フィーチャーフラグ</strong><div class=\"sns-muted\">機能公開設定を保存します。サイト本体側の接続後に表示制御へ反映されます。</div></div><button class=\"btn\" id=\"opsFlagsRefresh\">更新</button></div>\n   <form id=\"opsFlagForm\" class=\"ops-form\">\n    <div class=\"ops-form-grid\"><label>フラグキー<input id=\"opsFlagKey\" pattern=\"[a-z0-9][a-z0-9_-]{1,63}\" required placeholder=\"new_widget\"></label><label>表示名<input id=\"opsFlagLabel\" maxlength=\"80\" required placeholder=\"新ウィジェット\"></label></div>\n    <textarea id=\"opsFlagDescription\" maxlength=\"500\" rows=\"2\" placeholder=\"説明・対象機能\"></textarea>\n    <div class=\"ops-form-grid\"><label>公開割合（%）<input id=\"opsFlagRollout\" type=\"number\" min=\"0\" max=\"100\" step=\"1\" value=\"100\"></label><label class=\"ops-check\"><input id=\"opsFlagEnabled\" type=\"checkbox\"> 有効にする</label></div>\n    <div class=\"ops-form-actions\"><button type=\"submit\" class=\"btn primary\">フラグを保存</button><button class=\"btn\" type=\"reset\">入力をクリア</button></div>\n   </form>\n   <div class=\"list\" id=\"opsFlagsList\"><div class=\"empty\">読み込み中…</div></div>\n  </section>\n </div>\n <div id=\"opsAnalyticsView\" hidden>\n  <div class=\"toolbar\" style=\"padding-left:0;padding-right:0;border:0\">\n   <div><strong>KURO Lab 利用状況</strong><div class=\"sns-muted\">ログイン中ユーザーのページ閲覧・ウィジェット利用・APIエラーを集計します。</div></div>\n   <button class=\"btn\" id=\"opsAnalyticsRefresh\">更新</button>\n  </div>\n  <div class=\"ops-analytics-grid\">\n   <div class=\"ops-metric\"><small>DAU（今日）</small><strong id=\"opsDau\">—</strong></div>\n   <div class=\"ops-metric\"><small>MAU（30日）</small><strong id=\"opsMau\">—</strong></div>\n   <div class=\"ops-metric\"><small>DAU / MAU</small><strong id=\"opsDauMau\">—</strong></div>\n   <div class=\"ops-metric\"><small>ページ閲覧（30日）</small><strong id=\"opsPageViews\">—</strong></div>\n   <div class=\"ops-metric\"><small>セッション（30日）</small><strong id=\"opsSessions\">—</strong></div>\n   <div class=\"ops-metric\"><small>APIエラー（24時間）</small><strong id=\"opsApiErrors\">—</strong></div>\n   <div class=\"ops-metric\"><small>画面エラー（24時間）</small><strong id=\"opsClientErrors\">—</strong></div>\n   <div class=\"ops-metric\"><small>記録イベント（30日）</small><strong id=\"opsEvents\">—</strong></div>\n  </div>\n  <section class=\"panel ops-analytics-panel\">\n   <div class=\"toolbar\"><div><strong>日別アクティブユーザー</strong><div class=\"sns-muted\">日本時間・過去30日</div></div><span class=\"sns-muted\" id=\"opsAnalyticsUpdated\">集計準備中…</span></div>\n   <div id=\"opsActiveChart\" class=\"ops-active-chart\"><div class=\"empty\">読み込み中…</div></div>\n  </section>\n  <div class=\"ops-analytics-columns\">\n   <section class=\"panel ops-analytics-panel\">\n    <div class=\"toolbar\"><div><strong>ウィジェット利用ランキング</strong><div class=\"sns-muted\">閲覧・追加・削除（過去30日）</div></div></div>\n    <div class=\"ops-tablewrap\" id=\"opsWidgetRanking\"><div class=\"empty\">読み込み中…</div></div>\n   </section>\n   <section class=\"panel ops-analytics-panel\">\n    <div class=\"toolbar\"><div><strong>外部API・通信エラー</strong><div class=\"sns-muted\">成功率と失敗件数（過去7日）</div></div></div>\n    <div class=\"ops-tablewrap\" id=\"opsApiHealth\"><div class=\"empty\">読み込み中…</div></div>\n   </section>\n  </div>\n  <section class=\"panel ops-analytics-panel\">\n   <div class=\"toolbar\"><div><strong>定着率</strong><div class=\"sns-muted\">登録後1日・7日・30日以内に再訪した割合。計測開始後に登録したユーザーが対象です。</div></div></div>\n   <div class=\"ops-retention-grid\" id=\"opsRetention\"><div class=\"empty\">読み込み中…</div></div>\n   <div class=\"ops-meta\" id=\"opsTrackingNote\"></div>\n  </section>\n  <section class=\"panel ops-analytics-panel\">\n   <div class=\"toolbar\"><div><strong>ユーザー別エラーログ</strong><div class=\"sns-muted\">対象ユーザーのUUIDを入力。直近30日・最大100件。</div></div></div>\n   <form id=\"opsUserErrorsForm\" class=\"ops-form ops-error-search\"><input id=\"opsErrorUserId\" placeholder=\"ユーザーID（UUID）\" required><button class=\"btn primary\">エラーを検索</button></form>\n   <div class=\"list\" id=\"opsUserErrors\"><div class=\"empty\">ユーザーIDを入力して検索してください。</div></div>\n  </section>\n </div>\n</main>\n\n<main id=\"snsAdminSection\" class=\"wrap main\" hidden>\n <div class=\"eyebrow\">KURO SNS / Moderation</div>\n <div class=\"heading\">\n  <div><h1>KURO SNS 管理</h1><p>投稿・返信・利用者プロフィール・公開チャットを管理します。</p></div>\n  <div class=\"statusline\" id=\"snsConnection\">接続準備中…</div>\n </div>\n <div class=\"stats\">\n  <div class=\"stat\"><span>登録プロフィール</span><strong id=\"snsUsersCount\">—</strong></div>\n  <div class=\"stat\"><span>投稿</span><strong id=\"snsPostsCount\">—</strong></div>\n  <div class=\"stat\"><span>返信</span><strong id=\"snsRepliesCount\">—</strong></div>\n  <div class=\"stat\"><span>いいね</span><strong id=\"snsLikesCount\">—</strong></div>\n  <div class=\"stat\"><span>フォロー</span><strong id=\"snsFollowsCount\">—</strong></div>\n  <div class=\"stat\"><span>公開チャット</span><strong id=\"snsChatCount\">—</strong></div>\n </div>\n <section class=\"panel\">\n  <div class=\"toolbar\">\n   <div class=\"sns-tabs\" id=\"snsTabs\">\n    <button class=\"active\" data-sns-tab=\"posts\">投稿管理</button>\n    <button data-sns-tab=\"replies\">返信管理</button>\n    <button data-sns-tab=\"users\">利用者</button>\n    <button data-sns-tab=\"chat\">公開チャット</button>\n    <button data-sns-tab=\"analytics\">分析</button>\n   </div>\n   <div class=\"sns-toolbar-right\">\n    <div id=\"snsSearchWrap\"><input class=\"search\" id=\"snsSearch\" type=\"search\" placeholder=\"表示中の内容を検索…\"></div>\n    <select class=\"analytics-range\" id=\"snsAnalyticsRange\" aria-label=\"分析期間\" hidden><option value=\"7\">7日間</option><option value=\"14\" selected>14日間</option><option value=\"30\">30日間</option><option value=\"90\">90日間</option></select>\n    <button class=\"btn\" id=\"snsRefresh\">更新</button>\n   </div>\n  </div>\n  <div id=\"snsContextFilter\" class=\"sns-context\" hidden>特定の利用者の投稿を表示中 <button class=\"btn\" id=\"snsClearUserFilter\">解除</button></div>\n  <div id=\"snsPostsPanel\" class=\"list\"><div class=\"empty\">読み込み中…</div></div>\n  <div id=\"snsRepliesPanel\" class=\"list\" hidden><div class=\"empty\">読み込み中…</div></div>\n  <div id=\"snsUsersPanel\" class=\"list\" hidden><div class=\"empty\">読み込み中…</div></div>\n  <div id=\"snsChatPanel\" class=\"list\" hidden><div class=\"empty\">読み込み中…</div></div>\n  <div id=\"snsAnalyticsPanel\" class=\"list\" hidden>\n   <div class=\"analytics-intro\">\n    <div><strong>KURO SNS インサイト</strong><small>投稿・返信・フォローなどの動きを期間別に分析します。</small></div>\n    <div class=\"sns-muted\" id=\"snsAnalyticsUpdated\">集計準備中…</div>\n   </div>\n   <div class=\"analytics-summary\">\n    <div class=\"analytics-mini\"><small>期間内の新規登録</small><strong id=\"analyticsNewUsers\">—</strong></div>\n    <div class=\"analytics-mini\"><small>期間内の投稿</small><strong id=\"analyticsPosts\">—</strong></div>\n    <div class=\"analytics-mini\"><small>期間内の返信</small><strong id=\"analyticsReplies\">—</strong></div>\n    <div class=\"analytics-mini\"><small>期間内のいいね</small><strong id=\"analyticsLikes\">—</strong></div>\n   </div>\n   <div class=\"analytics-layout\">\n    <section class=\"analytics-card\">\n     <h3>日別アクティビティ</h3>\n     <div class=\"analytics-sub\" id=\"analyticsChartSubtitle\">投稿・返信・公開チャットの推移</div>\n     <div class=\"analytics-legend\">\n      <span><i class=\"analytics-dot\" style=\"background:#55b5f2\"></i>投稿</span>\n      <span><i class=\"analytics-dot\" style=\"background:#a78bfa\"></i>返信</span>\n      <span><i class=\"analytics-dot\" style=\"background:#55cda5\"></i>公開チャット</span>\n     </div>\n     <svg id=\"snsActivityChart\" class=\"analytics-chart\" viewBox=\"0 0 900 250\" role=\"img\" aria-label=\"日別アクティビティの折れ線グラフ\"></svg>\n     <div id=\"analyticsSummaryText\" class=\"analytics-sub\"></div>\n    </section>\n    <div class=\"analytics-side\">\n     <section class=\"analytics-card\"><h3>人気ハッシュタグ</h3><div class=\"analytics-sub\">取得できた投稿データから集計</div><ol id=\"snsTopHashtags\" class=\"analytics-rank\"></ol></section>\n     <section class=\"analytics-card\"><h3>投稿が多い利用者</h3><div class=\"analytics-sub\">取得できた投稿データから集計</div><ol id=\"snsTopContributors\" class=\"analytics-rank\"></ol></section>\n     <section class=\"analytics-card\"><h3>エンゲージメント</h3><div class=\"analytics-sub\">投稿1件あたりの「いいね＋返信」</div><strong id=\"snsEngagement\" style=\"font-size:28px\">—</strong></section>\n    </div>\n   </div>\n   <div id=\"analyticsDataNote\" class=\"analytics-note\"></div>\n  </div>\n </section>\n <p class=\"sns-muted\" style=\"margin:12px 4px 0\">安全のため、個人間チャットやグループ内の非公開メッセージはこの管理画面には表示しません。</p>\n</main>\n</div>\n<script>\n(function(){\n\"use strict\";\nconst SUPABASE_URL=\"https://cprvpphlfpmiegjiutjn.supabase.co\";\nconst PUBLISHABLE_KEY=\"sb_publishable_BYPUfB0lr2h26jV8_6ZQnpQ_wfAKOVyn\";\nconst $=s=>document.querySelector(s);\nconst MODE_KEY=\"kuro-admin-connection-mode\";\nconst mode=localStorage.getItem(MODE_KEY)===\"gas\"?\"gas\":\"supabase\";\nasync function gasFetch(input,init={}){\n const request=new Request(input,init);\n const target=new URL(request.url);\n if(target.origin!==SUPABASE_URL)return fetch(request);\n const bodyBuffer=[\"GET\",\"HEAD\"].includes(request.method)?new ArrayBuffer(0):await request.clone().arrayBuffer();\n const bytes=new Uint8Array(bodyBuffer);\n let binary=\"\";\n for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));\n const bodyBase64=bytes.length?btoa(binary):\"\";\n const headers=Object.fromEntries(request.headers.entries());\n const proxyResponse=await fetch(\"/api/kuro-gas-proxy\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({path:target.pathname+target.search,method:request.method,headers,bodyBase64,clientId:\"admin-console\"})});\n let result;\n try{result=await proxyResponse.json();}catch{throw new Error(\"GASプロキシからJSON以外の応答が返されました。\");}\n if(!proxyResponse.ok||!result||typeof result.status!==\"number\"){\n  throw new Error(result?.error||\"GAS経由の通信に失敗しました。\");\n }\n let responseBody=result.bodyText??\"\";\n if(result.isBinary&&result.bodyBase64){\n  const raw=atob(result.bodyBase64),out=new Uint8Array(raw.length);\n  for(let i=0;i<raw.length;i++)out[i]=raw.charCodeAt(i);\n  responseBody=out;\n }\n const status=result.status;\n return new Response([204,205,304].includes(status)?null:responseBody,{status,headers:result.headers||{}});\n}\nconst db=window.supabase.createClient(SUPABASE_URL,PUBLISHABLE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true},global:{fetch:mode===\"gas\"?gasFetch:fetch}});\nconst modeSelect=$(\"#modeSelect\"),modeSelectTop=$(\"#modeSelectTop\");\nconst PRODUCT_KEY=\"kuro-admin-product\";\nlet activeProduct=[\"lab\",\"sns\",\"ops\"].includes(localStorage.getItem(PRODUCT_KEY))?localStorage.getItem(PRODUCT_KEY):\"lab\";\nconst productSelect=$(\"#productSelect\");\nfunction syncModeSelectors(){if(modeSelect)modeSelect.value=mode;if(modeSelectTop)modeSelectTop.value=mode;}\nfunction syncProductSelector(){if(productSelect)productSelect.value=activeProduct;}\nfunction setMode(next){if(next!==\"gas\"&&next!==\"supabase\")return;localStorage.setItem(MODE_KEY,next);location.reload();}\nif(modeSelect)modeSelect.addEventListener(\"change\",()=>setMode(modeSelect.value));\nif(modeSelectTop)modeSelectTop.addEventListener(\"change\",()=>setMode(modeSelectTop.value));\nsyncModeSelectors();\nlet rows=[],filter=\"all\",channel=null,seen=new Set(),firstLoad=true;\nlet opsUsers=[],opsAuditLogs=[],opsAnnouncements=[],opsFlags=[],opsView='users',editingAnnouncementId=null;\nlet snsProfiles=[],snsPosts=[],snsReplies=[],snsChatMessages=[],snsTab=\"posts\",snsUserFilterId=null,refreshTimer=null;\nlet snsRealtimeChannel=null,snsReloadTimer=null,analyticsRefreshTimer=null,snsLikesTotal=0,snsFollowsTotal=0;\nconst labels={pending:\"未対応\",reviewing:\"確認中\",done:\"対応済み\"};\nconst esc=s=>String(s??\"\").replace(/[&<>\"']/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\nconst date=s=>new Intl.DateTimeFormat(\"ja-JP\",{dateStyle:\"medium\",timeStyle:\"short\"}).format(new Date(s));\nfunction showLogin(message){$(\"#appView\").hidden=true;$(\"#loginView\").hidden=false;if(message)$(\"#loginError\").textContent=message;}\nfunction showApp(user){$(\"#loginView\").hidden=true;$(\"#appView\").hidden=false;$(\"#account\").textContent=user.email||\"管理者\";$(\"#loginError\").textContent=\"\";}\nasync function checkAdmin(user){\n const {data,error}=await db.from(\"admin_users\").select(\"user_id,role\").eq(\"user_id\",user.id).maybeSingle();\n if(error)throw error;\n if(!data)throw new Error(\"このアカウントには管理者権限がありません。\");\n}\nasync function load(){\n $(\"#requestList\").innerHTML='<div class=\"empty\">読み込み中…</div>';\n const {data,error}=await db.from(\"portal_requests\").select(\"id,message,status,created_at,user_id\").order(\"created_at\",{ascending:false}).limit(300);\n if(error){$(\"#requestList\").innerHTML='<div class=\"error\">読み込みに失敗しました：'+esc(error.message)+'</div>';return;}\n rows=data||[];\n if(!firstLoad){rows.forEach(r=>{if(!seen.has(r.id)){seen.add(r.id);}});}\n else {rows.forEach(r=>seen.add(r.id));firstLoad=false;}\n render();\n}\nfunction render(){\n const counts={pending:0,reviewing:0,done:0};rows.forEach(r=>counts[r.status]=(counts[r.status]||0)+1);\n $(\"#totalCount\").textContent=rows.length;$(\"#pendingCount\").textContent=counts.pending||0;$(\"#reviewCount\").textContent=counts.reviewing||0;\n const q=$(\"#search\").value.trim().toLowerCase();\n const shown=rows.filter(r=>(filter===\"all\"||r.status===filter)&&(!q||r.message.toLowerCase().includes(q)));\n if(!shown.length){$(\"#requestList\").innerHTML='<div class=\"empty\">該当するリクエストはありません。</div>';return;}\n $(\"#requestList\").innerHTML=shown.map(r=>'<article class=\"item\"><div><div class=\"meta\"><span class=\"pill '+esc(r.status)+'\">'+esc(labels[r.status]||r.status)+'</span><span>'+esc(date(r.created_at))+'</span><span>'+(r.user_id?'ログイン利用者':'ゲスト')+'</span></div><p class=\"message\">'+esc(r.message)+'</p></div><div class=\"actions\"><select aria-label=\"ステータス\" data-status=\"'+esc(r.id)+'\"><option value=\"pending\" '+(r.status===\"pending\"?\"selected\":\"\")+'>未対応</option><option value=\"reviewing\" '+(r.status===\"reviewing\"?\"selected\":\"\")+'>確認中</option><option value=\"done\" '+(r.status===\"done\"?\"selected\":\"\")+'>対応済み</option></select><button class=\"btn primary\" data-save=\"'+esc(r.id)+'\">保存</button></div></article>').join(\"\");\n $(\"#requestList\").querySelectorAll(\"[data-save]\").forEach(b=>b.addEventListener(\"click\",()=>saveStatus(b.dataset.save,b)));\n}\nasync function saveStatus(id,button){\n const select=$(\"#requestList [data-status='\"+CSS.escape(id)+\"']\");\n const status=select.value;button.disabled=true;\n const {error}=await db.from(\"portal_requests\").update({status}).eq(\"id\",id);\n button.disabled=false;\n if(error){alert(\"更新できませんでした：\"+error.message);return;}\n const row=rows.find(x=>x.id===id);if(row)row.status=status;render();\n}\nfunction subscribe(){\n if(channel){db.removeChannel(channel);channel=null;}\n if(mode===\"gas\"){$(\"#connection\").textContent=\"GAS経由（45秒ごとに更新）\";return;}\n channel=db.channel(\"admin-portal-requests\").on(\"postgres_changes\",{event:\"INSERT\",schema:\"public\",table:\"portal_requests\"},payload=>{\n  const r=payload.new;if(!r||rows.some(x=>x.id===r.id))return;\n  rows.unshift(r);seen.add(r.id);render();$(\"#connection\").textContent=\"リアルタイム接続中\";\n  if(\"Notification\" in window&&Notification.permission===\"granted\")new Notification(\"KURO Lab｜新着リクエスト\",{body:String(r.message||\"新しいリクエストが届きました\").slice(0,100)});\n }).on(\"postgres_changes\",{event:\"UPDATE\",schema:\"public\",table:\"portal_requests\"},payload=>{\n  const i=rows.findIndex(x=>x.id===payload.new.id);if(i>=0)rows[i]=payload.new;render();\n }).subscribe(s=>{$(\"#connection\").textContent=s===\"SUBSCRIBED\"?\"リアルタイム接続中\":\"再接続待機中\";});\n}\n\nasync function loadSns(){\n const panels=[\"#snsPostsPanel\",\"#snsRepliesPanel\",\"#snsUsersPanel\",\"#snsChatPanel\"];\n panels.forEach(s=>$(s).innerHTML='<div class=\"empty\">読み込み中…</div>');\n const queries=await Promise.all([\n  db.from(\"profiles\").select(\"id,username,display_name,bio,avatar_url,created_at\",{count:\"exact\"}).order(\"created_at\",{ascending:false}).limit(500),\n  db.from(\"posts\").select(\"id,user_id,content,hashtags,created_at\",{count:\"exact\"}).order(\"created_at\",{ascending:false}).limit(500),\n  db.from(\"post_replies\").select(\"id,post_id,user_id,content,created_at\",{count:\"exact\"}).order(\"created_at\",{ascending:false}).limit(500),\n  db.from(\"public_chat_messages\").select(\"id,nickname,content,created_at\",{count:\"exact\"}).order(\"created_at\",{ascending:false}).limit(500),\n  db.from(\"post_likes\").select(\"post_id\",{count:\"exact\"}).limit(1),\n  db.from(\"follows\").select(\"follower_id\",{count:\"exact\"}).limit(1)\n ]);\n const failed=queries.find(q=>q.error);\n if(failed){\n  const message=esc(failed.error.message||\"読み込みに失敗しました。\");\n  panels.forEach(s=>$(s).innerHTML='<div class=\"error\">読み込みに失敗しました：'+message+'</div>');\n  $(\"#snsConnection\").textContent=\"通信エラー\";\n  return;\n }\n snsProfiles=queries[0].data||[];\n snsPosts=queries[1].data||[];\n snsReplies=queries[2].data||[];\n snsChatMessages=queries[3].data||[];\n snsLikesTotal=queries[4].count||0;\n snsFollowsTotal=queries[5].count||0;\n $(\"#snsUsersCount\").textContent=queries[0].count??snsProfiles.length;\n $(\"#snsPostsCount\").textContent=queries[1].count??snsPosts.length;\n $(\"#snsRepliesCount\").textContent=queries[2].count??snsReplies.length;\n $(\"#snsChatCount\").textContent=queries[3].count??snsChatMessages.length;\n $(\"#snsLikesCount\").textContent=snsLikesTotal;\n $(\"#snsFollowsCount\").textContent=snsFollowsTotal;\n renderSns();\n}\n\nfunction analyticsDateKey(value){\n const d=new Date(value);\n return d.getFullYear()+\"-\"+String(d.getMonth()+1).padStart(2,\"0\")+\"-\"+String(d.getDate()).padStart(2,\"0\");\n}\nasync function loadAnalytics(){\n const days=Number($(\"#snsAnalyticsRange\").value)||14;\n const start=new Date();start.setHours(0,0,0,0);start.setDate(start.getDate()-(days-1));\n const since=start.toISOString();\n $(\"#snsAnalyticsUpdated\").textContent=\"集計中…\";\n const queries=await Promise.all([\n  db.from(\"profiles\").select(\"id,created_at\",{count:\"exact\"}).gte(\"created_at\",since).order(\"created_at\",{ascending:true}).limit(1000),\n  db.from(\"posts\").select(\"id,user_id,hashtags,created_at\",{count:\"exact\"}).gte(\"created_at\",since).order(\"created_at\",{ascending:true}).limit(1000),\n  db.from(\"post_replies\").select(\"id,created_at\",{count:\"exact\"}).gte(\"created_at\",since).order(\"created_at\",{ascending:true}).limit(1000),\n  db.from(\"post_likes\").select(\"post_id,created_at\",{count:\"exact\"}).gte(\"created_at\",since).order(\"created_at\",{ascending:true}).limit(1000),\n  db.from(\"follows\").select(\"follower_id,created_at\",{count:\"exact\"}).gte(\"created_at\",since).order(\"created_at\",{ascending:true}).limit(1000),\n  db.from(\"public_chat_messages\").select(\"id,created_at\",{count:\"exact\"}).gte(\"created_at\",since).order(\"created_at\",{ascending:true}).limit(1000)\n ]);\n const failed=queries.find(q=>q.error);\n if(failed){\n  $(\"#snsAnalyticsUpdated\").textContent=\"集計に失敗\";\n  $(\"#snsActivityChart\").innerHTML='<text x=\"30\" y=\"110\">データを取得できませんでした：'+esc(failed.error.message)+'</text>';\n  return;\n }\n const data=queries.map(q=>q.data||[]);\n const totals=queries.map((q,i)=>q.count??data[i].length);\n $(\"#analyticsNewUsers\").textContent=totals[0];\n $(\"#analyticsPosts\").textContent=totals[1];\n $(\"#analyticsReplies\").textContent=totals[2];\n $(\"#analyticsLikes\").textContent=totals[3];\n const datePoints=Array.from({length:days},(_,i)=>{\n  const d=new Date(start);d.setDate(start.getDate()+i);\n  return {key:analyticsDateKey(d),label:d.toLocaleDateString(\"ja-JP\",{month:\"numeric\",day:\"numeric\"}),posts:0,replies:0,chat:0};\n });\n const byDay=new Map(datePoints.map(p=>[p.key,p]));\n for(const r of data[1]){const p=byDay.get(analyticsDateKey(r.created_at));if(p)p.posts++;}\n for(const r of data[2]){const p=byDay.get(analyticsDateKey(r.created_at));if(p)p.replies++;}\n for(const r of data[5]){const p=byDay.get(analyticsDateKey(r.created_at));if(p)p.chat++;}\n const series=[{key:\"posts\",css:\"series-posts\"},{key:\"replies\",css:\"series-replies\"},{key:\"chat\",css:\"series-chat\"}];\n const max=Math.max(1,...datePoints.flatMap(p=>series.map(s=>p[s.key])));\n const left=48,right=16,top=18,bottom=38,width=900,height=250,plotW=width-left-right,plotH=height-top-bottom;\n const x=i=>left+(datePoints.length===1?0:i*plotW/(datePoints.length-1));\n const y=v=>top+plotH-(v/max)*plotH;\n let svg=\"\";\n for(let i=0;i<=4;i++){\n  const val=Math.round(max*i/4),yy=y(val);\n  svg+='<line class=\"gridline\" x1=\"'+left+'\" y1=\"'+yy+'\" x2=\"'+(width-right)+'\" y2=\"'+yy+'\"></line><text x=\"'+(left-10)+'\" y=\"'+(yy+4)+'\" text-anchor=\"end\">'+val+'</text>';\n }\n for(const s of series){\n  const path=datePoints.map((p,i)=>(i===0?\"M\":\"L\")+x(i).toFixed(1)+\",\"+y(p[s.key]).toFixed(1)).join(\" \");\n  svg+='<path class=\"'+s.css+'\" d=\"'+path+'\"></path>';\n  if(datePoints.length<=30)datePoints.forEach((p,i)=>{svg+='<circle cx=\"'+x(i).toFixed(1)+'\" cy=\"'+y(p[s.key]).toFixed(1)+'\" r=\"3\" fill=\"'+(s.key===\"posts\"?\"#55b5f2\":s.key===\"replies\"?\"#a78bfa\":\"#55cda5\")+'\"></circle>';});\n }\n const labelIndexes=[0,Math.round((days-1)*.25),Math.round((days-1)*.5),Math.round((days-1)*.75),days-1];\n [...new Set(labelIndexes)].forEach(i=>{const p=datePoints[i];if(p)svg+='<text x=\"'+x(i)+'\" y=\"'+(height-10)+'\" text-anchor=\"middle\">'+p.label+'</text>';});\n $(\"#snsActivityChart\").innerHTML=svg;\n $(\"#analyticsChartSubtitle\").textContent=days+\"日間の日別投稿・返信・公開チャット\";\n const hashtagCounts=new Map();\n snsPosts.forEach(p=>(p.hashtags||[]).forEach(tag=>{const t=String(tag).replace(/^#/,\"\").trim();if(t)hashtagCounts.set(t,(hashtagCounts.get(t)||0)+1);}));\n const tagList=[...hashtagCounts.entries()].sort((a,b)=>b[1]-a[1]).slice(0,6);\n $(\"#snsTopHashtags\").innerHTML=tagList.length?tagList.map(([tag,n])=>'<li><span>#'+esc(tag)+'</span><b>'+n+'</b></li>').join(\"\"):'<li class=\"analytics-empty\">まだ集計できるタグがありません。</li>';\n const users=new Map();\n snsPosts.forEach(p=>users.set(p.user_id,(users.get(p.user_id)||0)+1));\n const topUsers=[...users.entries()].sort((a,b)=>b[1]-a[1]).slice(0,5);\n $(\"#snsTopContributors\").innerHTML=topUsers.length?topUsers.map(([id,n])=>{\n  const profile=snsProfiles.find(p=>p.id===id);\n  return '<li><span>'+esc(profile?.display_name||profile?.username||\"利用者\")+(profile?.username?' <small>@'+esc(profile.username)+'</small>':'')+'</span><b>'+n+'</b></li>';\n }).join(\"\"):'<li class=\"analytics-empty\">投稿データがありません。</li>';\n const postTotal=Number($(\"#snsPostsCount\").textContent)||0;\n $(\"#snsEngagement\").textContent=postTotal?((snsLikesTotal+(Number($(\"#snsRepliesCount\").textContent)||0))/postTotal).toFixed(2):\"—\";\n const sums=datePoints.reduce((a,p)=>({posts:a.posts+p.posts,replies:a.replies+p.replies,chat:a.chat+p.chat}),{posts:0,replies:0,chat:0});\n $(\"#analyticsSummaryText\").textContent=\"期間内の合計：投稿 \"+totals[1]+\" 件／返信 \"+totals[2]+\" 件／いいね \"+totals[3]+\" 件／フォロー \"+totals[4]+\" 件／公開チャット \"+totals[5]+\" 件\";\n const capped=queries.some((q,i)=>(q.count??0)>data[i].length);\n $(\"#analyticsDataNote\").textContent=(capped?\"一部テーブルで取得上限に達しています。日別グラフは取得できた先頭1,000件の範囲です。\":\"期間内のデータをすべて取得しています。\")+\" 人気タグ・投稿者ランキングは管理画面に読み込んだ最新500投稿を対象にしています。\";\n $(\"#snsAnalyticsUpdated\").textContent=\"最終更新：\"+new Date().toLocaleTimeString(\"ja-JP\");\n}\nfunction stopSnsRealtime(){\n if(snsRealtimeChannel){db.removeChannel(snsRealtimeChannel);snsRealtimeChannel=null;}\n if(snsReloadTimer){clearTimeout(snsReloadTimer);snsReloadTimer=null;}\n}\nfunction queueSnsRealtimeRefresh(){\n if(snsReloadTimer)clearTimeout(snsReloadTimer);\n snsReloadTimer=setTimeout(async()=>{\n  if(activeProduct!==\"sns\")return;\n  await loadSns();\n  if(snsTab===\"analytics\")await loadAnalytics();\n },350);\n}\nfunction startSnsRealtime(){\n stopSnsRealtime();\n if(mode===\"gas\"){\n  $(\"#snsConnection\").textContent=\"GAS版・15秒ごとに自動同期\";\n  return;\n }\n const channel=db.channel(\"kuro-sns-admin-live\");\n [\"profiles\",\"posts\",\"post_replies\",\"post_likes\",\"follows\",\"public_chat_messages\"].forEach(table=>{\n  channel.on(\"postgres_changes\",{event:\"*\",schema:\"public\",table},queueSnsRealtimeRefresh);\n });\n snsRealtimeChannel=channel.subscribe(status=>{\n  if(activeProduct!==\"sns\")return;\n  $(\"#snsConnection\").innerHTML=status===\"SUBSCRIBED\"?'<span class=\"live-pulse\"></span>リアルタイム接続中':status===\"CHANNEL_ERROR\"?\"リアルタイム接続エラー\":status===\"TIMED_OUT\"?\"接続タイムアウト\":\"リアルタイム接続中…\";\n });\n}\n\nfunction snsProfileLabel(userId){\n const p=snsProfiles.find(x=>x.id===userId);\n return p?esc(p.display_name||p.username)+\" <span class=\\\"sns-muted\\\">@\"+esc(p.username)+\"</span>\":\"<span class=\\\"sns-muted\\\">プロフィール未登録</span>\";\n}\nfunction renderSns(){\n const query=($(\"#snsSearch\").value||\"\").trim().toLowerCase();\n [\"posts\",\"replies\",\"users\",\"chat\",\"analytics\"].forEach(tab=>{\n  const panel=$(\"#sns\"+tab.charAt(0).toUpperCase()+tab.slice(1)+\"Panel\");\n  if(panel)panel.hidden=snsTab!==tab;\n  const button=$(\"#snsTabs [data-sns-tab='\"+tab+\"']\");\n  if(button)button.classList.toggle(\"active\",snsTab===tab);\n });\n $(\"#snsSearchWrap\").hidden=snsTab===\"analytics\";\n $(\"#snsAnalyticsRange\").hidden=snsTab!==\"analytics\";\n $(\"#snsContextFilter\").hidden=!snsUserFilterId;\n const profileById=id=>snsProfiles.find(p=>p.id===id);\n if(snsTab===\"posts\"){\n  const shown=snsPosts.filter(r=>{\n   const p=profileById(r.user_id);\n   const text=[r.content,(r.hashtags||[]).join(\" \"),p?.username,p?.display_name].join(\" \").toLowerCase();\n   return (!snsUserFilterId||r.user_id===snsUserFilterId)&&(!query||text.includes(query));\n  });\n  $(\"#snsPostsPanel\").innerHTML=shown.length?shown.map(r=>'<article class=\"item\"><div><div class=\"meta\"><strong>'+snsProfileLabel(r.user_id)+'</strong><span>'+esc(date(r.created_at))+'</span></div><p class=\"sns-text\">'+esc(r.content)+'</p><div class=\"sns-muted\">'+esc((r.hashtags||[]).join(\" \"))+' · '+snsReplies.filter(x=>x.post_id===r.id).length+' 件の返信</div></div><div class=\"sns-actions\"><button class=\"btn\" data-sns-delete=\"post\" data-id=\"'+esc(r.id)+'\">投稿を削除</button></div></article>').join(\"\"):'<div class=\"empty\">該当する投稿はありません。</div>';\n }\n if(snsTab===\"replies\"){\n  const shown=snsReplies.filter(r=>{\n   const p=profileById(r.user_id),parent=snsPosts.find(x=>x.id===r.post_id);\n   return !query||[r.content,p?.username,p?.display_name,parent?.content].join(\" \").toLowerCase().includes(query);\n  });\n  $(\"#snsRepliesPanel\").innerHTML=shown.length?shown.map(r=>'<article class=\"item\"><div><div class=\"meta\"><strong>'+snsProfileLabel(r.user_id)+'</strong><span>'+esc(date(r.created_at))+'</span></div><p class=\"sns-text\">'+esc(r.content)+'</p><div class=\"sns-muted\">元の投稿：'+esc((snsPosts.find(x=>x.id===r.post_id)||{}).content||\"投稿が見つかりません\")+'</div></div><div class=\"sns-actions\"><button class=\"btn\" data-sns-delete=\"reply\" data-id=\"'+esc(r.id)+'\">返信を削除</button></div></article>').join(\"\"):'<div class=\"empty\">該当する返信はありません。</div>';\n }\n if(snsTab===\"users\"){\n  const shown=snsProfiles.filter(p=>!query||[p.display_name,p.username,p.bio].join(\" \").toLowerCase().includes(query));\n  $(\"#snsUsersPanel\").innerHTML=shown.length?shown.map(p=>'<article class=\"item\"><div><div class=\"meta\"><strong>'+esc(p.display_name||p.username)+'</strong><span>@'+esc(p.username)+'</span><span>登録 '+esc(date(p.created_at))+'</span></div><p class=\"sns-text\">'+esc(p.bio||\"自己紹介はありません。\")+'</p><div class=\"sns-muted\">投稿 '+snsPosts.filter(x=>x.user_id===p.id).length+' 件 · 返信 '+snsReplies.filter(x=>x.user_id===p.id).length+' 件</div></div><div class=\"sns-actions\"><button class=\"btn\" data-sns-user-posts=\"'+esc(p.id)+'\">この利用者の投稿</button></div></article>').join(\"\"):'<div class=\"empty\">該当する利用者はいません。</div>';\n }\n if(snsTab===\"chat\"){\n  const shown=snsChatMessages.filter(r=>!query||[r.nickname,r.content].join(\" \").toLowerCase().includes(query));\n  $(\"#snsChatPanel\").innerHTML=shown.length?shown.map(r=>'<article class=\"item\"><div><div class=\"meta\"><strong>'+esc(r.nickname)+'</strong><span>'+esc(date(r.created_at))+'</span></div><p class=\"sns-text\">'+esc(r.content)+'</p></div><div class=\"sns-actions\"><button class=\"btn\" data-sns-delete=\"chat\" data-id=\"'+esc(r.id)+'\">メッセージを削除</button></div></article>').join(\"\"):'<div class=\"empty\">該当する公開チャットはありません。</div>';\n }\n}\nasync function deleteSnsItem(type,id,button){\n const config={\n  post:{table:\"posts\",label:\"投稿\",list:snsPosts},\n  reply:{table:\"post_replies\",label:\"返信\",list:snsReplies},\n  chat:{table:\"public_chat_messages\",label:\"公開チャットのメッセージ\",list:snsChatMessages}\n }[type];\n if(!config||!config.list.some(x=>x.id===id))return;\n if(!confirm(\"この\"+config.label+\"を削除します。元に戻せません。実行しますか？\"))return;\n if(button)button.disabled=true;\n const {data,error}=await db.from(config.table).delete().eq(\"id\",id).select(\"id\");\n if(button)button.disabled=false;\n if(error){alert(\"削除できませんでした：\"+error.message);return;}\n if(!data||!data.length){alert(\"削除されませんでした。管理者権限または削除ポリシーを確認してください。\");return;}\n await loadSns();\n}\n\nfunction opsIsBanned(user){return !!user.banned_until&&new Date(user.banned_until).getTime()>Date.now();}\nfunction renderOpsUsers(){\n const query=($(\"#opsUsersSearch\").value||\"\").trim().toLowerCase();\n const status=$(\"#opsStatusFilter\").value,created=$(\"#opsCreatedFilter\").value;\n const activity=$(\"#opsActivityFilter\").value,boards=$(\"#opsBoardsFilter\").value,plan=$(\"#opsPlanFilter\").value;\n const now=Date.now();\n const shown=opsUsers.filter(u=>{\n  const banned=opsIsBanned(u),last=u.last_sign_in_at?new Date(u.last_sign_in_at).getTime():0;\n  const registered=u.created_at?new Date(u.created_at).getTime():0;\n  const q=[u.email,u.username,u.display_name,u.id].join(\" \").toLowerCase();\n  if(query&&!q.includes(query))return false;\n  if(status===\"active\"&&banned)return false;\n  if(status===\"banned\"&&!banned)return false;\n  if(created!==\"all\"&&(!registered||now-registered>Number(created)*86400000))return false;\n  if(activity===\"never\"&&last)return false;\n  if([\"7\",\"30\",\"90\"].includes(activity)&&(!last||now-last>Number(activity)*86400000))return false;\n  if(boards===\"0\"&&u.board_count!==0)return false;\n  if(boards===\"1\"&&u.board_count!==1)return false;\n  if(boards===\"2-5\"&&(u.board_count<2||u.board_count>5))return false;\n  if(boards===\"6\"&&u.board_count<6)return false;\n  if(plan===\"free\"&&u.plan!==\"free\")return false;\n  if(plan===\"paid\"&&u.plan!==\"pro\"&&u.plan!==\"paid\")return false;\n  if(plan===\"unlinked\"&&u.plan!==\"unlinked\")return false;\n  return true;\n });\n const active=opsUsers.filter(u=>!opsIsBanned(u)).length;\n $(\"#opsTotalUsers\").textContent=opsUsers.length;\n $(\"#opsActiveUsers\").textContent=active;\n $(\"#opsBannedUsers\").textContent=opsUsers.length-active;\n $(\"#opsUsersMeta\").textContent=shown.length+\" / \"+opsUsers.length+\" 件を表示 · プラン情報は課金連携が完了するまで未連携です。\";\n if(!shown.length){$(\"#opsUsersList\").innerHTML='<div class=\"empty\">条件に一致するユーザーはいません。</div>';return;}\n $(\"#opsUsersList\").innerHTML='<table class=\"ops-table\"><thead><tr><th>ユーザー</th><th>登録日時</th><th>最終ログイン</th><th>ボード</th><th>ウィジェット</th><th>プラン</th><th>状態</th><th>操作</th></tr></thead><tbody>'+\n shown.map(u=>{\n  const banned=opsIsBanned(u);\n  return '<tr><td><strong>'+esc(u.display_name||u.username||\"名称未設定\")+'</strong><small>'+esc(u.email||\"メール未登録\")+'</small><small>'+esc(u.id)+'</small></td>'+\n   '<td>'+esc(u.created_at?date(u.created_at):\"—\")+'</td>'+\n   '<td>'+esc(u.last_sign_in_at?date(u.last_sign_in_at):\"記録なし\")+'</td>'+\n   '<td>'+Number(u.board_count||0)+'</td><td>'+Number(u.widget_count||0)+'</td>'+\n   '<td><span class=\"ops-plan\">'+(u.plan===\"free\"?\"無料\":(u.plan===\"pro\"||u.plan===\"paid\"?\"有料\":\"未連携\"))+'</span></td>'+\n   '<td><span class=\"ops-status '+(banned?\"banned\":\"\")+'\">'+(banned?\"停止中\":\"利用可能\")+'</span></td>'+\n   '<td><div class=\"ops-user-actions\">'+\n    (banned?'<button class=\"btn\" data-ops-action=\"unban\" data-user-id=\"'+esc(u.id)+'\">解除</button>':'<button class=\"btn\" data-ops-action=\"ban\" data-user-id=\"'+esc(u.id)+'\">停止</button>')+\n    '<button class=\"btn\" data-ops-action=\"reset\" data-user-id=\"'+esc(u.id)+'\">再設定メール</button>'+\n   '</div></td></tr>';\n }).join(\"\")+'</tbody></table>';\n}\nasync function loadOpsUsers(){\n $(\"#opsUsersList\").innerHTML='<div class=\"empty\">読み込み中…</div>';\n $(\"#opsConnection\").textContent=\"アカウント情報を取得中…\";\n const {data,error}=await db.functions.invoke(\"admin-console\",{body:{action:\"list_users\",page:1}});\n if(error||data?.error){\n  const message=error?.message||data?.error||\"不明なエラー\";\n  $(\"#opsUsersList\").innerHTML='<div class=\"error\">読み込みに失敗しました：'+esc(message)+'</div>';\n  $(\"#opsConnection\").textContent=\"通信エラー\";\n  return;\n }\n opsUsers=Array.isArray(data?.users)?data.users:[];\n renderOpsUsers();\n $(\"#opsConnection\").textContent=\"接続済み · \"+new Date().toLocaleTimeString(\"ja-JP\");\n}\nasync function runOpsUserAction(button){\n const action=button.dataset.opsAction,userId=button.dataset.userId,user=opsUsers.find(u=>u.id===userId);\n if(!user)return;\n let payload;\n if(action===\"ban\"){\n  const reason=window.prompt(\"停止理由を入力してください（監査ログに保存されます）。\",\"規約違反\");\n  if(reason===null)return;\n  if(!window.confirm((user.email||user.id)+\" を停止します。ログインできなくなります。続行しますか？\"))return;\n  payload={action:\"set_ban\",userId,enabled:true,reason};\n }else if(action===\"unban\"){\n  if(!window.confirm((user.email||user.id)+\" の停止を解除しますか？\"))return;\n  payload={action:\"set_ban\",userId,enabled:false,reason:\"管理者による停止解除\"};\n }else if(action===\"reset\"){\n  if(!window.confirm((user.email||user.id)+\" にパスワード再設定メールを送信しますか？\"))return;\n  payload={action:\"send_password_reset\",userId};\n }else return;\n button.disabled=true;\n const {data,error}=await db.functions.invoke(\"admin-console\",{body:payload});\n button.disabled=false;\n if(error||data?.error){alert(\"操作に失敗しました：\"+(error?.message||data?.error||\"不明なエラー\"));return;}\n alert(action===\"ban\"?\"アカウントを停止しました。\":action===\"unban\"?\"停止を解除しました。\":\"再設定メールの送信を要求しました。\");\n await loadOpsUsers();\n}\n\n\nfunction setOpsView(view){\n opsView=view;\n [\"users\",\"audit\",\"announcements\",\"flags\",\"analytics\"].forEach(name=>{\n  const target=$(\"#ops\"+name.charAt(0).toUpperCase()+name.slice(1)+\"View\");\n  if(target)target.hidden=name!==view;\n  const button=$(\"#opsTabs [data-ops-tab='\"+name+\"']\");\n  if(button)button.classList.toggle(\"active\",name===view);\n });\n if(view===\"users\")loadOpsUsers();\n if(view===\"audit\")loadOpsAudit();\n if(view===\"announcements\")loadOpsAnnouncements();\n if(view===\"flags\")loadOpsFlags();\n if(view===\"analytics\")loadOpsAnalytics();\n}\nasync function opsInvoke(body){\n const {data,error}=await db.functions.invoke(\"admin-console\",{body});\n if(error)throw error;\n if(data?.error)throw new Error(data.error);\n return data;\n}\nasync function loadOpsAudit(){\n $(\"#opsAuditList\").innerHTML='<div class=\"empty\">読み込み中…</div>';\n try{\n  const data=await opsInvoke({action:\"list_audit\",limit:200});\n  opsAuditLogs=data.logs||[];\n  $(\"#opsAuditList\").innerHTML=opsAuditLogs.length?opsAuditLogs.map(log=>\n   '<article class=\"ops-ann-item\"><div class=\"ops-ann-copy\"><div class=\"meta\"><strong>'+esc(log.action)+'</strong><span>'+esc(date(log.created_at))+'</span></div>'+\n   '<div class=\"ops-audit-meta\">管理者：'+esc(log.actor_user_id||\"不明\")+'<br>対象：'+esc(log.target_user_id||\"—\")+'<br>'+esc(JSON.stringify(log.metadata||{}))+'</div></div></article>'\n  ).join(\"\"):'<div class=\"empty\">監査ログはまだありません。</div>';\n }catch(e){$(\"#opsAuditList\").innerHTML='<div class=\"error\">読み込みに失敗しました：'+esc(e.message)+'</div>';}\n}\nasync function loadOpsAnnouncements(){\n $(\"#opsAnnouncementsList\").innerHTML='<div class=\"empty\">読み込み中…</div>';\n try{\n  const data=await opsInvoke({action:\"list_announcements\"});\n  opsAnnouncements=data.announcements||[];\n  $(\"#opsAnnouncementsList\").innerHTML=opsAnnouncements.length?opsAnnouncements.map(item=>\n   '<article class=\"ops-ann-item\"><div class=\"ops-ann-copy\"><div class=\"meta\"><strong>'+esc(item.title)+'</strong><span class=\"ops-status '+(item.published?\"\":\"banned\")+'\">'+(item.published?\"公開\":\"非公開\")+'</span><span>'+esc(date(item.created_at))+'</span></div><p>'+esc(item.body)+'</p><div class=\"sns-muted\">開始：'+esc(date(item.starts_at))+' · 終了：'+esc(item.ends_at?date(item.ends_at):\"指定なし\")+(item.href?' · '+esc(item.href):'')+'</div></div><div class=\"ops-inline-actions\"><button class=\"btn\" data-ann-edit=\"'+esc(item.id)+'\">編集</button>'+(item.published?'<button class=\"btn\" data-ann-unpublish=\"'+esc(item.id)+'\">非公開</button>':'')+'</div></article>'\n  ).join(\"\"):'<div class=\"empty\">お知らせはまだありません。</div>';\n }catch(e){$(\"#opsAnnouncementsList\").innerHTML='<div class=\"error\">読み込みに失敗しました：'+esc(e.message)+'</div>';}\n}\nasync function loadOpsFlags(){\n $(\"#opsFlagsList\").innerHTML='<div class=\"empty\">読み込み中…</div>';\n try{\n  const data=await opsInvoke({action:\"list_feature_flags\"});\n  opsFlags=data.flags||[];\n  $(\"#opsFlagsList\").innerHTML=opsFlags.length?opsFlags.map(flag=>\n   '<article class=\"ops-flag-item\"><div class=\"ops-flag-copy\"><div class=\"meta\"><strong>'+esc(flag.label)+'</strong><span class=\"ops-flag-key\">'+esc(flag.key)+'</span><span class=\"ops-status '+(flag.enabled?\"\":\"banned\")+'\">'+(flag.enabled?\"有効\":\"無効\")+'</span><span>'+Number(flag.rollout_percentage)+'%</span></div><div class=\"sns-muted\">'+esc(flag.description||\"説明なし\")+'</div></div><div class=\"ops-inline-actions\"><button class=\"btn\" data-flag-edit=\"'+esc(flag.key)+'\">編集</button><button class=\"btn\" data-flag-delete=\"'+esc(flag.key)+'\">削除</button></div></article>'\n  ).join(\"\"):'<div class=\"empty\">フラグはまだ登録されていません。</div>';\n }catch(e){$(\"#opsFlagsList\").innerHTML='<div class=\"error\">読み込みに失敗しました：'+esc(e.message)+'</div>';}\n}\nfunction resetAnnouncementForm(){\n editingAnnouncementId=null;$(\"#opsAnnouncementForm\").reset();\n const local=new Date(Date.now()-new Date().getTimezoneOffset()*60000);\n $(\"#opsAnnStarts\").value=local.toISOString().slice(0,16);\n $(\"#opsAnnSave\").textContent=\"お知らせを保存\";$(\"#opsAnnCancel\").hidden=true;\n}\nfunction editAnnouncement(id){\n const item=opsAnnouncements.find(x=>x.id===id);if(!item)return;\n editingAnnouncementId=id;$(\"#opsAnnTitle\").value=item.title||\"\";\n $(\"#opsAnnBody\").value=item.body||\"\";$(\"#opsAnnHref\").value=item.href||\"\";\n $(\"#opsAnnPublished\").checked=!!item.published;\n const toLocal=value=>{if(!value)return \"\";const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};\n $(\"#opsAnnStarts\").value=toLocal(item.starts_at);$(\"#opsAnnEnds\").value=toLocal(item.ends_at);\n $(\"#opsAnnSave\").textContent=\"変更を保存\";$(\"#opsAnnCancel\").hidden=false;\n $(\"#opsAnnStatus\").textContent=\"編集中：\"+item.title;\n $(\"#opsAnnouncementForm\").scrollIntoView({behavior:\"smooth\",block:\"start\"});\n}\nasync function saveAnnouncement(event){\n event.preventDefault();const button=$(\"#opsAnnSave\");button.disabled=true;\n try{\n  const starts=$(\"#opsAnnStarts\").value?new Date($(\"#opsAnnStarts\").value).toISOString():null;\n  const ends=$(\"#opsAnnEnds\").value?new Date($(\"#opsAnnEnds\").value).toISOString():null;\n  await opsInvoke({action:\"save_announcement\",id:editingAnnouncementId||undefined,title:$(\"#opsAnnTitle\").value,content:$(\"#opsAnnBody\").value,href:$(\"#opsAnnHref\").value,starts_at:starts,ends_at:ends,published:$(\"#opsAnnPublished\").checked});\n  $(\"#opsAnnStatus\").textContent=\"保存しました。\";resetAnnouncementForm();\n  await loadOpsAnnouncements();await loadOpsAudit();\n }catch(e){alert(\"保存できませんでした：\"+e.message);}\n finally{button.disabled=false;}\n}\nasync function unpublishAnnouncement(id){\n const item=opsAnnouncements.find(x=>x.id===id);if(!item)return;\n if(!confirm(\"「\"+item.title+\"」を非公開にしますか？\"))return;\n try{await opsInvoke({action:\"unpublish_announcement\",id});await loadOpsAnnouncements();await loadOpsAudit();}\n catch(e){alert(\"非公開にできませんでした：\"+e.message);}\n}\nfunction editFeatureFlag(key){\n const flag=opsFlags.find(x=>x.key===key);if(!flag)return;\n $(\"#opsFlagKey\").value=flag.key;$(\"#opsFlagKey\").readOnly=true;\n $(\"#opsFlagLabel\").value=flag.label;$(\"#opsFlagDescription\").value=flag.description||\"\";\n $(\"#opsFlagRollout\").value=flag.rollout_percentage;$(\"#opsFlagEnabled\").checked=!!flag.enabled;\n $(\"#opsFlagForm\").scrollIntoView({behavior:\"smooth\",block:\"start\"});\n}\nasync function saveFeatureFlag(event){\n event.preventDefault();const button=$(\"#opsFlagForm button[type='submit']\");button.disabled=true;\n try{\n  await opsInvoke({action:\"save_feature_flag\",key:$(\"#opsFlagKey\").value,label:$(\"#opsFlagLabel\").value,description:$(\"#opsFlagDescription\").value,rollout_percentage:Number($(\"#opsFlagRollout\").value),enabled:$(\"#opsFlagEnabled\").checked});\n  $(\"#opsFlagForm\").reset();$(\"#opsFlagKey\").readOnly=false;$(\"#opsFlagRollout\").value=100;\n  await loadOpsFlags();await loadOpsAudit();\n }catch(e){alert(\"保存できませんでした：\"+e.message);}\n finally{button.disabled=false;}\n}\nasync function deleteFeatureFlag(key){\n if(!confirm(\"フラグ「\"+key+\"」を削除しますか？\"))return;\n try{await opsInvoke({action:\"delete_feature_flag\",key});await loadOpsFlags();await loadOpsAudit();}\n catch(e){alert(\"削除できませんでした：\"+e.message);}\n}\n\nasync function loadOpsAnalytics(){\n $(\"#opsActiveChart\").innerHTML='<div class=\"empty\">集計中…</div>';\n try{\n  const data=await opsInvoke({action:\"get_usage_analytics\"});\n  const n=v=>Number(v||0).toLocaleString(\"ja-JP\");\n  $(\"#opsDau\").textContent=n(data.dau);\n  $(\"#opsMau\").textContent=n(data.mau);\n  $(\"#opsDauMau\").textContent=Number(data.dau_mau_rate||0).toFixed(1)+\"%\";\n  $(\"#opsPageViews\").textContent=n(data.page_views_30d);\n  $(\"#opsSessions\").textContent=n(data.sessions_30d);\n  $(\"#opsApiErrors\").textContent=n(data.api_errors_24h);\n  $(\"#opsClientErrors\").textContent=n(data.client_errors_24h);\n  $(\"#opsEvents\").textContent=n(data.events_30d);\n  $(\"#opsAnalyticsUpdated\").textContent=\"更新：\"+new Date(data.generated_at).toLocaleString(\"ja-JP\");\n  const daily=Array.isArray(data.daily)?data.daily:[];\n  const max=Math.max(1,...daily.map(x=>Number(x.active_users||0)));\n  $(\"#opsActiveChart\").innerHTML=daily.length?daily.map(x=>{\n   const v=Number(x.active_users||0),h=Math.max(2,Math.round(v/max*126));\n   return '<div class=\"ops-chart-day\" title=\"'+esc(x.date)+'：'+n(v)+'人\"><b style=\"font-size:10px;color:var(--muted)\">'+n(v)+'</b><div class=\"ops-chart-bar\" style=\"height:'+h+'px\"></div><small>'+esc(x.date.slice(5))+'</small></div>';\n  }).join(\"\"):'<div class=\"empty\">まだ閲覧データがありません。ログインしてポータルを利用すると記録されます。</div>';\n  const widgets=Array.isArray(data.widgets)?data.widgets:[];\n  $(\"#opsWidgetRanking\").innerHTML=widgets.length?'<table class=\"ops-analytics-table\"><thead><tr><th>ウィジェット</th><th>閲覧</th><th>追加</th><th>削除</th></tr></thead><tbody>'+widgets.map(x=>'<tr><td>'+esc(x.widget_key)+'</td><td>'+n(x.views)+'</td><td>'+n(x.adds)+'</td><td>'+n(x.removes)+'</td></tr>').join(\"\")+'</tbody></table>':'<div class=\"empty\">ウィジェット利用データはまだありません。</div>';\n  const apis=Array.isArray(data.apis)?data.apis:[];\n  $(\"#opsApiHealth\").innerHTML=apis.length?'<table class=\"ops-analytics-table\"><thead><tr><th>サービス</th><th>要求</th><th>失敗</th><th>失敗率</th></tr></thead><tbody>'+apis.map(x=>'<tr><td>'+esc(x.service_key)+'</td><td>'+n(x.requests)+'</td><td>'+n(x.errors)+'</td><td>'+Number(x.error_rate||0).toFixed(1)+'%</td></tr>').join(\"\")+'</tbody></table>':'<div class=\"empty\">API通信データはまだありません。</div>';\n  const retention=data.retention||{};\n  const rcard=(label,x)=>'<div class=\"ops-retention-card\"><small>'+label+' 継続率</small><strong>'+(x&&x.rate!==null&&x.rate!==undefined?Number(x.rate).toFixed(1)+\"%\":\"—\")+'</strong><small>対象 '+n(x&&x.eligible)+' 人 · 再訪 '+n(x&&x.retained)+' 人</small></div>';\n  $(\"#opsRetention\").innerHTML=rcard(\"翌日\",retention.day1)+rcard(\"7日後\",retention.day7)+rcard(\"30日後\",retention.day30);\n  $(\"#opsTrackingNote\").textContent=\"計測開始：\"+(data.tracking_started_at?new Date(data.tracking_started_at).toLocaleString(\"ja-JP\"):\"まだ記録なし\")+(data.truncated?\" · イベント数が上限に達したため一部省略\":\"\")+(data.user_list_truncated?\" · ユーザー一覧は上限まで取得\":\"\");\n }catch(e){\n  $(\"#opsActiveChart\").innerHTML='<div class=\"error\">分析データを取得できませんでした：'+esc(e.message)+'</div>';\n  $(\"#opsAnalyticsUpdated\").textContent=\"取得失敗\";\n }\n}\nasync function loadOpsUserErrors(event){\n event.preventDefault();\n const id=$(\"#opsErrorUserId\").value.trim();\n if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)){alert(\"正しいUUIDを入力してください。\");return;}\n $(\"#opsUserErrors\").innerHTML='<div class=\"empty\">検索中…</div>';\n try{\n  const data=await opsInvoke({action:\"get_user_error_log\",userId:id});\n  const logs=Array.isArray(data.logs)?data.logs:[];\n  $(\"#opsUserErrors\").innerHTML=logs.length?logs.map(x=>'<article class=\"ops-error-item\"><b>'+esc(x.event_name)+'</b> · '+esc(x.error_code||\"エラー\")+'<small>'+esc(date(x.created_at))+' · '+esc(x.page_key||\"\")+' · '+esc(x.widget_key||\"\")+' · '+esc(x.service_key||\"\")+' · '+esc(x.status_code||\"\")+'</small></article>').join(\"\"):'<div class=\"empty\">直近30日に記録されたエラーはありません。</div>';\n }catch(e){$(\"#opsUserErrors\").innerHTML='<div class=\"error\">検索に失敗しました：'+esc(e.message)+'</div>';}\n}\n\nfunction startAdminPolling(){\n if(refreshTimer)clearInterval(refreshTimer);\n const interval=activeProduct===\"sns\"&&mode===\"gas\"?15000:45000;\n refreshTimer=setInterval(()=>{\n  if($(\"#appView\").hidden)return;\n  if(activeProduct===\"lab\")load();\n  else if(activeProduct===\"sns\"){\n   loadSns();\n   if(snsTab===\"analytics\")loadAnalytics();\n  }else if(activeProduct===\"ops\"){\n   if(opsView===\"users\")loadOpsUsers();\n   else if(opsView===\"audit\")loadOpsAudit();\n   else if(opsView===\"announcements\")loadOpsAnnouncements();\n   else if(opsView===\"flags\")loadOpsFlags();\n   else loadOpsAnalytics();\n  }\n },interval);\n}\nasync function switchProduct(){\n activeProduct=[\"lab\",\"sns\",\"ops\"].includes(productSelect?.value)?productSelect.value:\"lab\";\n localStorage.setItem(PRODUCT_KEY,activeProduct);\n syncProductSelector();\n if(channel){await db.removeChannel(channel);channel=null;}\n stopSnsRealtime();\n $(\"#labAdminSection\").hidden=activeProduct!==\"lab\";\n $(\"#snsAdminSection\").hidden=activeProduct!==\"sns\";\n $(\"#opsAdminSection\").hidden=activeProduct!==\"ops\";\n if(activeProduct===\"lab\"){await load();subscribe();}\n else if(activeProduct===\"sns\"){\n  await loadSns();\n  startSnsRealtime();\n  if(snsTab===\"analytics\")await loadAnalytics();\n }else setOpsView(opsView);\n startAdminPolling();\n}\n\nasync function enter(user){\n try{\n  await checkAdmin(user);showApp(user);syncModeSelectors();syncProductSelector();\n  await switchProduct();\n\n }catch(e){await db.auth.signOut();showLogin(e.message||\"管理者認証に失敗しました。\");}\n}\n$(\"#loginForm\").addEventListener(\"submit\",async e=>{\n e.preventDefault();const b=$(\"#loginButton\");b.disabled=true;$(\"#loginError\").textContent=\"\";\n try{const {data,error}=await db.auth.signInWithPassword({email:$(\"#email\").value.trim(),password:$(\"#password\").value});if(error)throw error;await enter(data.user);}\n catch(err){$(\"#loginError\").textContent=err.message||\"ログインできませんでした。\";}\n finally{b.disabled=false;}\n});\n$(\"#logoutButton\").addEventListener(\"click\",async()=>{if(channel)await db.removeChannel(channel);await db.auth.signOut();showLogin(\"\");});\n$(\"#notifyButton\").addEventListener(\"click\",async()=>{if(!(\"Notification\" in window)){alert(\"このブラウザは通知に対応していません。\");return;}const p=await Notification.requestPermission();$(\"#notifyButton\").textContent=p===\"granted\"?\"通知は有効\":\"通知を許可\";});\n$(\"#filters\").addEventListener(\"click\",e=>{const b=e.target.closest(\"button[data-filter]\");if(!b)return;filter=b.dataset.filter;$(\"#filters\").querySelectorAll(\"button\").forEach(x=>x.classList.toggle(\"active\",x===b));render();});\n$(\"#search\").addEventListener(\"input\",render);\n$(\"#productSelect\").addEventListener(\"change\",switchProduct);\n$(\"#opsUsersRefresh\").addEventListener(\"click\",loadOpsUsers);\n$(\"#opsUsersSearch\").addEventListener(\"input\",renderOpsUsers);\n[\"opsStatusFilter\",\"opsCreatedFilter\",\"opsActivityFilter\",\"opsBoardsFilter\",\"opsPlanFilter\"].forEach(id=>$(\"#\"+id).addEventListener(\"change\",renderOpsUsers));\n$(\"#opsUsersList\").addEventListener(\"click\",e=>{const b=e.target.closest(\"button[data-ops-action]\");if(b)runOpsUserAction(b);});\n$(\"#opsTabs\").addEventListener(\"click\",e=>{const b=e.target.closest(\"button[data-ops-tab]\");if(b)setOpsView(b.dataset.opsTab);});\n$(\"#opsAuditRefresh\").addEventListener(\"click\",loadOpsAudit);\n$(\"#opsAnnouncementsRefresh\").addEventListener(\"click\",loadOpsAnnouncements);\n$(\"#opsFlagsRefresh\").addEventListener(\"click\",loadOpsFlags);\n$(\"#opsAnalyticsRefresh\").addEventListener(\"click\",loadOpsAnalytics);\n$(\"#opsUserErrorsForm\").addEventListener(\"submit\",loadOpsUserErrors);\n$(\"#opsAnnouncementForm\").addEventListener(\"submit\",saveAnnouncement);\n$(\"#opsAnnCancel\").addEventListener(\"click\",resetAnnouncementForm);\n$(\"#opsAnnouncementsList\").addEventListener(\"click\",e=>{const edit=e.target.closest(\"[data-ann-edit]\"),off=e.target.closest(\"[data-ann-unpublish]\");if(edit)editAnnouncement(edit.dataset.annEdit);if(off)unpublishAnnouncement(off.dataset.annUnpublish);});\n$(\"#opsFlagForm\").addEventListener(\"submit\",saveFeatureFlag);\n$(\"#opsFlagForm\").addEventListener(\"reset\",()=>{setTimeout(()=>{$(\"#opsFlagKey\").readOnly=false;$(\"#opsFlagRollout\").value=100;},0);});\n$(\"#opsFlagsList\").addEventListener(\"click\",e=>{const edit=e.target.closest(\"[data-flag-edit]\"),del=e.target.closest(\"[data-flag-delete]\");if(edit)editFeatureFlag(edit.dataset.flagEdit);if(del)deleteFeatureFlag(del.dataset.flagDelete);});\n\n\n$(\"#snsTabs\").addEventListener(\"click\",async e=>{\n const b=e.target.closest(\"button[data-sns-tab]\");if(!b)return;\n snsTab=b.dataset.snsTab;renderSns();\n if(snsTab===\"analytics\")await loadAnalytics();\n});\n$(\"#snsSearch\").addEventListener(\"input\",renderSns);\n$(\"#snsRefresh\").addEventListener(\"click\",async()=>{await loadSns();if(snsTab===\"analytics\")await loadAnalytics();});\n$(\"#snsAnalyticsRange\").addEventListener(\"change\",loadAnalytics);\n$(\"#snsClearUserFilter\").addEventListener(\"click\",()=>{snsUserFilterId=null;renderSns();});\n$(\"#snsAdminSection\").addEventListener(\"click\",e=>{\n const del=e.target.closest(\"button[data-sns-delete]\");\n if(del){deleteSnsItem(del.dataset.snsDelete,del.dataset.id,del);return;}\n const user=e.target.closest(\"button[data-sns-user-posts]\");\n if(user){snsUserFilterId=user.dataset.snsUserPosts;snsTab=\"posts\";$(\"#snsSearch\").value=\"\";renderSns();}\n});\ndb.auth.getSession().then(({data})=>{if(data.session)enter(data.session.user);});\ndb.auth.onAuthStateChange((event,session)=>{if(event===\"SIGNED_OUT\")showLogin(\"\");});\n})();\n</script>\n</body></html>"
function isSafeWorkspaceFeedUrl(value) {
  try {
    const u = new URL(value);
    if (u.protocol !== "https:" || u.username || u.password) return false;
    if (u.port && u.port !== "443") return false;
    const host = u.hostname.toLowerCase().replace(/\.$/, "");
    if (!host || host === "localhost" || host.endsWith(".localhost") || host.endsWith(".local") || host.endsWith(".internal") || host === "metadata.google.internal" || host.includes(":")) return false;
    if (/^\d{1,3}(?:\.\d{1,3}){3}$/.test(host)) return false;
    if (!/^[a-z0-9.-]+$/.test(host) || !host.includes(".")) return false;
    return true;
  } catch (_) {
    return false;
  }
}

async function workspaceRss(request) {
  if (request.method !== "GET") {
    return new Response("Method not allowed", { status: 405, headers: { "Allow": "GET" } });
  }
  const input = new URL(request.url).searchParams.get("url") || "";
  if (!isSafeWorkspaceFeedUrl(input)) {
    return new Response("A public HTTPS RSS / Atom URL is required.", {
      status: 400,
      headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" }
    });
  }

  let target = new URL(input);
  let upstream;
  try {
    for (let attempt = 0; attempt < 4; attempt++) {
      if (!isSafeWorkspaceFeedUrl(target.href)) {
        return new Response("Redirect target is not allowed.", { status: 400 });
      }
      upstream = await fetch(target.href, {
        method: "GET",
        redirect: "manual",
        headers: {
          "Accept": "application/atom+xml, application/rss+xml, application/rdf+xml, application/xml, text/xml, text/plain;q=0.8",
          "User-Agent": "KURO-Lab-Workspace-Feed/1.0"
        }
      });
      if ([301, 302, 303, 307, 308].includes(upstream.status)) {
        const location = upstream.headers.get("Location");
        if (!location || attempt === 3) {
          return new Response("Too many feed redirects.", { status: 502 });
        }
        target = new URL(location, target);
        continue;
      }
      break;
    }

    if (!upstream || !upstream.ok) {
      return new Response("Feed source returned an error.", { status: 502, headers: { "Cache-Control": "no-store" } });
    }

    const type = (upstream.headers.get("Content-Type") || "").toLowerCase();
    if (!/(rss|atom|xml|rdf|text\/plain)/.test(type)) {
      return new Response("The source did not return an XML feed.", { status: 415, headers: { "Cache-Control": "no-store" } });
    }
    const length = Number(upstream.headers.get("Content-Length") || 0);
    if (length > 1048576) return new Response("Feed is too large.", { status: 413 });
    if (!upstream.body) return new Response("Empty feed.", { status: 502 });

    const reader = upstream.body.getReader();
    const chunks = [];
    let total = 0;
    while (true) {
      const part = await reader.read();
      if (part.done) break;
      total += part.value.byteLength;
      if (total > 1048576) {
        await reader.cancel();
        return new Response("Feed is too large.", { status: 413 });
      }
      chunks.push(part.value);
    }
    const body = new Uint8Array(total);
    let offset = 0;
    for (const chunk of chunks) {
      body.set(chunk, offset);
      offset += chunk.byteLength;
    }
    return new Response(new TextDecoder().decode(body), {
      status: 200,
      headers: {
        "Content-Type": "application/xml; charset=utf-8",
        "Cache-Control": "public, max-age=300",
        "X-Content-Type-Options": "nosniff"
      }
    });
  } catch (_) {
    return new Response("Unable to retrieve this feed.", {
      status: 502,
      headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" }
    });
  }
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (url.hostname === "kurolab.cc.cd" && (url.pathname === "/admin" || url.pathname === "/admin/")) {
      return new Response(ADMIN_HTML, {
        headers: {
          "Content-Type": "text/html; charset=utf-8",
          "Cache-Control": "private, no-store, max-age=0",
          "X-Robots-Tag": "noindex, nofollow, noarchive",
          "X-Content-Type-Options": "nosniff",
          "Referrer-Policy": "same-origin",
          "Strict-Transport-Security": "max-age=31536000; includeSubDomains",
          "X-Frame-Options": "DENY",
          "Permissions-Policy": "camera=(), microphone=(), geolocation=()"
        }
      });
    }

    if (url.hostname === "kurolab.cc.cd" && url.pathname === "/") {
      const response = await env.ASSETS.fetch(request);
      const html = await response.text();
      const updated = html.includes("href=\"/admin/\"") ? html : html.replace("<a href=\"/contact/\">お問い合わせ</a>", "<a href=\"/contact/\">お問い合わせ</a><a href=\"/admin/\">管理者</a>");
      const headers = new Headers(response.headers);
      headers.set("Cache-Control", "no-store");
      return new Response(updated, { status: response.status, statusText: response.statusText, headers });
    }

    if (url.hostname === "admin.kurolab.cc.cd") {
      if (url.pathname === "/" || url.pathname === "/admin/index.html") {
        return new Response(ADMIN_HTML, {
          headers: {
            "Content-Type": "text/html; charset=utf-8",
            "Cache-Control": "private, no-store, max-age=0",
            "X-Robots-Tag": "noindex, nofollow, noarchive",
            "X-Content-Type-Options": "nosniff",
            "Referrer-Policy": "same-origin",
            "Strict-Transport-Security": "max-age=31536000; includeSubDomains",
            "X-Frame-Options": "DENY",
            "Permissions-Policy": "camera=(), microphone=(), geolocation=()"
          }
        });
      }
      const response = await env.ASSETS.fetch(request);
      const headers = new Headers(response.headers);
      headers.set("Cache-Control", "private, no-store, max-age=0");
      headers.set("X-Robots-Tag", "noindex, nofollow, noarchive");
      headers.set("X-Content-Type-Options", "nosniff");
      return new Response(response.body, {
        status: response.status,
        statusText: response.statusText,
        headers
      });
    }

    if (url.pathname === "/api/workspace-rss") {
      return workspaceRss(request);
    }

    if (url.pathname === "/api/kuro-gas-proxy") {
      return gasProxy({
        request,
        env,
        params: {},
        waitUntil: (promise) => ctx.waitUntil(promise),
        next: () => env.ASSETS.fetch(request)
      });
    }

    return env.ASSETS.fetch(request);
  }
};
